                    if sum(v == 8 for v in row) >= max(3, (w * 2) // 5)]
        if not barriers:
            return [row[:] for row in a]

        sr, sc = src
        flipped = sr > barriers[-1]
        if flipped:
            a = a[::-1]
            sr = h - 1 - sr
            barriers = [h - 1 - r for r in barriers]
            barriers.sort()

        out = [row[:] for row in a]

        def paint(r, c):
            if 0 <= r < h and 0 <= c < w and a[r][c] == 0:
                out[r][c] = 2

        gaps = {r: [c for c, v in enumerate(a[r]) if v == 0]
                for r in barriers}

        first = barriers[0]
        first_gaps = gaps[first]

        # The marker's incoming track connects to the openings of the first
        # barrier on the row immediately before it.
        for r in range(sr + 1, first - 1):
            paint(r, sc)
