                        paint(rr, c)

                all_cols = current + following
                if all_cols:
                    for c in range(min(all_cols), max(all_cols) + 1):
                        paint(nr - 1, c)
                for c in following:
                    paint(nr, c)
            else:
                for rr in range(r + 1, h):
                    for c in current:
                        paint(rr, c)

        if flipped:
            out.reverse()
        return out

    h, w = len(grid), len(grid[0])
    transposed = [list(row) for row in zip(*grid)]

    def barrier_count(a):
        width = len(a[0])
        return sum(sum(v == 8 for v in row) >= max(3, (width * 2) // 5)
                   for row in a)

    if barrier_count(transposed) > barrier_count(grid):
        routed = route(transposed)
        return [list(row) for row in zip(*routed)]
    return route(grid)
